#pragma once
#include <array>
#include <string>
#include <vector>
namespace moon::help {
struct Article {std::string id,category;std::array<std::u32string,2> title;std::vector<std::array<std::u32string,2>> steps;std::array<std::u32string,2> tip;std::vector<std::string> shortcuts;};
inline const std::vector<Article>& helpArticles(){static const std::vector<Article> values{
{"first-art","start",{U"完成第一张像素画",U"Create your first pixel artwork"},{{U"在「文件 → 新建」设置画布尺寸。初次练习可以从 32 × 32 像素开始。",U"Choose File → New and set the canvas size. Try 32 × 32 pixels for a first exercise."},{U"在工具栏选择铅笔，在调色板选颜色，然后在画布上绘制。用橡皮擦除，用吸管拾取已有颜色。",U"Select the pencil and a palette color, then draw on the canvas. Use the eraser to remove pixels and the eyedropper to pick existing colors."},{U"通过图层面板添加图层，把线稿、颜色或背景分开；绘制前确认当前选中的图层。",U"Add layers in the Layers panel to separate outlines, colors and backgrounds. Check the active layer before drawing."},{U"用「文件 → 保存」保留可继续编辑的工程，再用「文件 → 导出」生成用于分享的图片。",U"Use File → Save to keep an editable project, then File → Export to create an image for sharing."}},{U"放大画布只是改变观看比例，不会增加图片像素。",U"Zooming changes the view, not the number of pixels in your image."},{"newDocument","tool.pencil","tool.eraser","tool.eyedropper","save"}},
{"selection","create",{U"选中、移动与变换局部内容",U"Select, move and transform part of an image"},{{U"先确认当前图层和帧，再用矩形、椭圆、套索或魔棒选出要编辑的区域。",U"Check the active layer and frame, then select an area using a rectangle, ellipse, lasso or magic wand."},{U"选择移动工具拖动选中内容，或用方向键微调位置。注意区分移动像素与调整选区边界。",U"Use the Move tool to drag selected content, or use arrow keys for small adjustments. Moving pixels and changing a selection boundary are different operations."},{U"需要缩放或旋转时使用变换，完成后确认变换；继续绘制前，按需要取消选区。",U"Use Transform to scale or rotate, then confirm the transformation. Deselect when you want to draw outside that area."},{U"同时编辑多个图层或帧前，检查图层面板和时间轴中的选中范围；不确定时先在单层单帧上操作。",U"Before editing multiple layers or frames, check the selected range in Layers and the timeline. Start with one layer and one frame if unsure."}},{U"画笔只能作用于有效选区内。看起来“画不出来”时，先检查是否还留着选区。",U"Painting is limited to the active selection. If strokes seem to do nothing, check for a remaining selection."},{"tool.selection","lasso","magic","tool.move","transform","deselect"}},
{"animation","create",{U"制作逐帧动画",U"Create a frame-by-frame animation"},{{U"在时间轴中选择当前帧，完成第一帧的图像。",U"Select the current frame in the timeline and draw the first pose."},{U"添加动画帧，再修改下一帧的姿态。想让两帧内容独立变化时，留意是否使用了链接帧。",U"Add an animation frame and edit the next pose. Check whether cels are linked if you want frames to change independently."},{U"打开洋葱皮参考相邻帧；播放动画检查动作，再调整帧时长和画面。",U"Enable onion skin to reference neighboring frames. Play the animation, then adjust frame durations and poses."},{U"分享时导出动画 GIF；交给游戏引擎时可导出精灵表或帧序列。",U"Export an animated GIF for sharing, or a sprite sheet or frame sequence for a game engine."}},{U"链接的单元格共享内容；改动一处可能影响其他链接帧。",U"Linked cels share content. Editing one can affect other linked frames."},{"addAnimationFrame","toggleOnionSkin","toggleAnimationPlayback"}},
{"color","create",{U"调整颜色与使用滤镜",U"Adjust colors and apply filters"},{{U"先选好图层、帧和需要处理的区域，再从「编辑」菜单选择颜色调整或滤镜。",U"Select the layer, frame and area to process, then choose a color adjustment or filter from Edit."},{U"用色相与饱和度调整整体色调，用曲线调整明暗，用渐变映射重新分配颜色。",U"Use Hue/Saturation to shift colors, Curves to adjust tones, and Gradient Map to remap colors."},{U"在支持实时预览的窗口中比较效果；满意后确认，不需要则取消。复杂画布上可关闭实时预览再调整参数。",U"Compare the result in dialogs that support live preview. Confirm to keep it or cancel to discard it. On complex canvases, turn off live preview while changing parameters."}},{U"较大的调整前先保存工程，或复制图层用于比较原图。",U"Save your project or duplicate the layer before a major adjustment."},{"adjustmentHueSaturation","adjustmentCurves"}},
{"export","start",{U"保存工程与导出素材",U"Save projects and export assets"},{{U"保存工程用于保留后续编辑需要的信息；导出图片用于分享或在其他软件中使用，两者用途不同。",U"Save a project to preserve editable information. Export images for sharing or use in other software."},{U"需要另存一个版本时使用「另存为」，避免覆盖想保留的工程。",U"Use Save As to keep a separate version without overwriting the project you want to retain."},{U"静态素材选择图片导出；动画选择 GIF、帧序列或精灵表，并检查输出范围、尺寸与透明背景。",U"For static artwork, export an image. For animation, choose GIF, a frame sequence or a sprite sheet, and check the range, dimensions and transparency."},{U"导出后打开结果确认尺寸、颜色和动画播放。PNG 适合需要透明背景的静态素材。",U"Open the exported result to check dimensions, colors and animation playback. PNG works well for static assets with transparency."}},{U"导出一张 PNG 不等于保存了可编辑的多图层工程。",U"Exporting a PNG does not save an editable multilayer project."},{"save","saveAs","exportDocument","exportSpriteSheet"}},
{"workspace","start",{U"调整视图、面板与快捷键",U"Arrange your view, panels and shortcuts"},{{U"用抓手移动画布视图，用缩放工具改变观看比例。不要用移动工具代替抓手，移动工具会编辑内容。",U"Use the Hand tool to pan and Zoom to change magnification. The Move tool edits content; use Hand when you only want to move the view."},{U"面板不见时先检查「窗口」菜单中的显示选项；根据工作习惯调整图层、调色板和时间轴。",U"If a panel is missing, check visibility options in Window. Arrange Layers, Palette and the timeline for your workflow."},{U"点击下方「快捷键设置」查看或修改按键。本帮助显示的是当前设置，而不是固定的默认快捷键。",U"Open Shortcut settings below to inspect or change bindings. Shortcuts shown here reflect your current settings, not fixed defaults."}},{U"旋转或镜像视图用于观察作品；修改实际像素时，应使用内容变换命令。",U"Rotate or mirror the view to inspect your artwork. Use content transformation commands to change the actual pixels."},{"tool.hand","tool.zoom","openShortcutSettings"}},
{"cannot-draw","fix",{U"画不出来、只画出一部分",U"Strokes are missing or clipped"},{{U"检查当前图层是否可见、是否锁定，以及是否选中了可绘制的图层和正确的动画帧。",U"Check that the active layer is visible, unlocked and paintable, and that the correct animation frame is selected."},{U"检查是否有残留选区；不需要限制范围时取消选区。",U"Look for an active selection. Deselect if you do not want to restrict painting."},{U"检查画笔大小、不透明度和当前颜色的透明度，再换一个明显的颜色试画。",U"Check brush size, opacity and the selected color’s alpha, then try a clearly visible color."},{U"如果变换或预览窗口还未完成，先确认或取消当前操作，再返回画布。",U"If a transformation or preview dialog is still active, confirm or cancel it before returning to the canvas."}},{U"先检查这些状态，可以避免误以为画布内容丢失而重复绘制。",U"Check these states before repainting content that may only be hidden or clipped."},{"deselect","tool.pencil"}},
{"undo","fix",{U"突然无法撤销怎么办",U"Undo suddenly stops working"},{{U"先松开鼠标或数位笔，确认没有正在拖动、绘制或尚未结束的变换操作。",U"Release the mouse or pen and check for an unfinished stroke, drag or transformation."},{U"退出文字输入框，再使用「编辑」菜单中的撤销。输入框获得焦点时，按键可能只作用于文字。",U"Leave any text field, then use Undo in the Edit menu. While a text field has focus, keys may affect only its text."},{U"检查撤销菜单是否可用。没有可撤销记录时，重复按快捷键不会恢复内容；关闭并重新打开工程也不等于恢复上次会话的撤销历史。",U"Check whether Undo is available. Repeated shortcuts cannot restore content without history; reopening a project does not restore the previous session’s undo history."},{U"若刚画的笔触也无法撤销，先另存当前作品，再打开诊断日志。记录使用的工具、上一项操作、是否使用数位板，以及菜单撤销是否也失效。",U"If even a fresh stroke cannot be undone, save a separate copy first and open diagnostic logs. Note the tool, preceding action, pen/tablet use and whether menu Undo also fails."}},{U"不要为了尝试恢复撤销而直接关闭未保存的工程。",U"Do not close an unsaved project just to try to restore Undo."},{"undo","redo","saveAs"}},
{"missing-content","fix",{U"移动后内容不见或位置不对",U"Content disappears or moves unexpectedly"},{{U"先查看当前帧、图层可见性和选中范围，确认没有切到另一帧或隐藏图层。",U"Check the current frame, layer visibility and selection range for an accidental frame switch or hidden layer."},{U"检查是否把内容移到了画布外，或同时选中了多个图层、帧。停止继续编辑，按需要撤销刚才的移动。",U"Check whether content moved outside the canvas or multiple layers or frames were selected. Stop further edits and undo the move if needed."},{U"重新操作时先只选一个图层和帧，区分移动内容与平移视图，观察哪一步开始异常。",U"Retry on one layer and frame. Distinguish moving content from panning the view, and note the first step that behaves incorrectly."},{U"问题重复出现时，另存工程副本并记录复现步骤，附上截图和诊断日志。",U"If the issue repeats, save a project copy and record reproduction steps, screenshots and diagnostic logs."}},{U"检查可见性和帧之前，不要急着合并图层或覆盖原工程。",U"Check visibility and frames before merging layers or overwriting the original project."},{"undo","tool.hand","tool.move"}},
{"recovery","fix",{U"异常退出、备份与问题反馈",U"Recovery, backups and reporting problems"},{{U"异常退出后重新打开软件，检查首页提供的恢复草稿；恢复后先另存并检查内容。",U"After an unexpected exit, reopen the app and check recovery drafts on the home screen. Save a recovered copy and inspect its contents."},{U"如果已启用工程备份，可从「文件」菜单的回档入口查看可用备份；是否能恢复取决于是否已有有效备份。",U"If project backups were enabled, use the rollback entry in File to inspect available backups. Recovery depends on having a valid backup."},{U"反馈问题时提供软件版本、操作步骤、预期与实际结果，以及截图或录屏。涉及工程时，优先提供能复现问题的最小副本。",U"When reporting a problem, include the app version, steps, expected and actual results, and a screenshot or recording. Provide a minimal project copy if possible."},{U"使用下方「诊断日志」打开日志位置，选取问题发生时的记录；分享前检查文件中是否包含不希望公开的信息。",U"Use Diagnostic logs below to open the log location and find records from the time of the issue. Check for information you do not want to share before sending files."}},{U"恢复草稿和可选备份不能代替主动保存；恢复前保留现有工程副本。",U"Recovery drafts and optional backups do not replace regular saves. Keep a copy of the current project before restoring."},{"save","saveAs"}},
{"canvas-size","start",{U"加大画布，还是放大图像？",U"Canvas size or image size?"},{{U"想在角色周围增加留白：使用「画布尺寸」，增加宽高，并通过锚点决定原内容保留在哪一侧。",U"To add space around a character, use Canvas Size, increase dimensions and choose an anchor to position existing content."},{U"例如把 32 × 32 扩展为 64 × 64：居中锚点适合四周留白；左上锚点适合向右、向下扩展。角色本身不会因此变大。",U"For example, expand 32 × 32 to 64 × 64. Center the anchor for space on all sides, or use the top-left anchor to extend right and down. The character itself stays the same size."},{U"想把整个角色放大：使用「图像尺寸」。保持宽高比例可以避免角色被拉长或压扁。",U"To enlarge the character itself, use Image Size. Preserve the aspect ratio to avoid stretching or squashing it."},{U"像素画放大时优先选择最近邻插值和整数倍率，例如 200% 或 400%，减少模糊与像素宽度不均。",U"For pixel art, prefer nearest-neighbor interpolation and integer scales such as 200% or 400% to avoid blur and uneven pixel widths."},{U"缩小画布前检查边界和裁切选项；缩小图像会丢失细节，先另存副本再处理。",U"Check boundaries and trimming options before shrinking the canvas. Reducing image size loses detail, so save a copy first."}},{U"只想看得更清楚时使用缩放视图，不必修改画布或图像尺寸。",U"To see details more clearly, zoom the view instead of changing canvas or image dimensions."},{"canvasResize","imageResize","viewZoom100","saveAs"}},
{"layers","create",{U"用图层管理线稿、上色和背景",U"Organize outlines, colors and backgrounds"},{{U"把背景放在下方，颜色放中间，线稿放上方。先选图层再画，避免把线稿和底色画到一起。",U"Place the background below colors and outlines above them. Select a layer before drawing to keep these elements separate."},{U"为图层起清楚的名字；角色、背景等多层内容可放入图层组，方便整理。",U"Give layers clear names. Use groups to organize multiple layers belonging to a character or background."},{U"临时隐藏图层检查遮挡关系；锁定不需要修改的图层，减少误操作。隐藏不等于删除。",U"Temporarily hide layers to inspect overlap. Lock layers you do not need to edit. Hiding a layer does not delete it."},{U"尝试大幅修改前复制图层。需要比较效果时切换原层和副本的可见性，避免两份内容同时显示影响判断。",U"Duplicate a layer before major edits. Compare by switching visibility between the original and copy rather than displaying both."},{U"合并前确认层顺序、透明度和效果。合并会减少独立编辑的空间，建议在工程副本中进行。",U"Before merging, check layer order, opacity and effects. Merging limits separate editing, so consider working in a project copy."}},{U"移动工具选中了意外的图层时，检查自动选层选项，或先手动选好目标层。",U"If Move selects an unexpected layer, check auto-select or select the target layer manually."},{"newLayer","createLayerGroup","duplicateLayer","toggleSelectedLayerLock","toggleMoveAutoSelect"}},
{"fill","create",{U"油漆桶漏色、填不满怎么调",U"Control bucket fill and color leaks"},{{U"先选择目标图层、颜色和油漆桶，在封闭区域内点击填色。填色前确认没有多余选区限制范围。",U"Select the target layer, color and bucket, then click inside a closed area. Check for selections that may restrict the fill."},{U"颜色漏到外面时，放大检查轮廓缺口。可先补上线条；工具支持智能闭合时，也可尝试启用后比较结果。",U"If color leaks out, zoom in and check for gaps in the outline. Close them manually, or try smart closure when available."},{U"边缘留下细缝时，检查是否有接近但不相同的颜色。逐步提高容差，每次观察边缘，避免吞掉线稿。",U"If narrow gaps remain, inspect similar but nonidentical colors. Increase tolerance gradually and watch the edges to avoid replacing outlines."},{U"连续选项用于限制连通区域；关闭后可能影响其他位置的相似颜色。只想填一个封闭区域时先使用连续模式。",U"Contiguous mode restricts the connected region. Turning it off can affect similar colors elsewhere. Start with contiguous mode for a single enclosed area."},{U"在空白颜色层上填色时，检查当前工具的取样范围；只取样空白层时，其他层的线稿可能不会形成边界。",U"When filling on an empty color layer, check the tool’s sampling scope. Sampling only that empty layer may ignore outlines on another layer."}},{U"填色结果不对，先撤销再调整参数，不要连续点击叠加错误结果。",U"Undo an incorrect fill before changing settings instead of repeatedly filling over it."},{"tool.fill","toggleContiguous","toggleSmartClosure","undo"}},
{"precise-selection","create",{U"精确选区：魔棒、加选与减选",U"Precise selections: wand, add and subtract"},{{U"规则区域用矩形或椭圆，不规则轮廓用套索，沿同色区域选择时用魔棒。",U"Use rectangles or ellipses for regular areas, a lasso for irregular outlines, and the wand for color-based areas."},{U"选区没有覆盖完整目标时，切到加选模式继续选择；选多了则切到减选模式移除多余区域。",U"Use Add mode to extend a selection and Subtract mode to remove unwanted areas."},{U"魔棒选得太少时逐步提高容差；选到背景时降低容差，并检查取样的是当前层还是可见层。",U"Increase wand tolerance gradually if too little is selected. Lower it if the background is included, and check current-layer versus visible-layer sampling."},{U"选中主体后需要处理背景，可以反选。操作前观察选区边界，确认将被修改的是哪一侧。",U"Invert a subject selection to work on the background. Check the outline before editing to confirm which side is selected."},{U"选区边框隐藏不代表选区已取消。绘制被限制但看不到边框时，显示选区边框或直接取消选区。",U"Hiding the selection outline does not deselect. If painting is restricted without a visible outline, show it or deselect."}},{U"选区确定编辑范围，图层和帧决定编辑对象；三者都需要检查。",U"The selection defines the area; layers and frames define the target. Check all three."},{"magic","selectionModeAdd","selectionModeSubtract","invertSelection","toggleSelectionOutline","deselect"}},
{"brushes","create",{U"调整笔刷并制作重复图案",U"Adjust brushes and make reusable stamps"},{{U"精修像素边缘时先使用小尺寸铅笔；大面积铺色再增大笔刷。检查不透明度，避免误把半透明笔触当成颜色错误。",U"Use a small pencil for pixel edges and a larger brush for broad areas. Check opacity if colors appear unexpectedly faint."},{U"需要稳定的笔触形状时，在工具选项中选择圆形、方形等笔刷形状；先在空白图层试画一笔。",U"Choose a brush shape such as round or square in tool options, then test it on an empty layer."},{U"把星星、草丛等小图案框选起来，使用「从选区创建笔刷」制成可重复绘制的图像笔刷。",U"Select a small motif such as a star or tuft of grass and use Create Brush from Selection to make a reusable image brush."},{U"在笔刷库中选择素材并试画，检查尺寸、间距和当前工具选项是否符合预期，再用于正式图层。",U"Choose a brush in the library and test its size, spacing and tool options before applying it to the artwork."}},{U"数位笔笔触变化异常时，先用鼠标对比，再检查笔压映射和笔刷动态设置。",U"If pen strokes behave unexpectedly, compare with a mouse, then check pressure mapping and brush dynamics."},{"brushSizeDecrease","brushSizeIncrease","brushShapeSquare","createBrushFromSelection","toggleBrushLibraryPanel"}},
{"palette","create",{U"建立统一配色与替换颜色",U"Build a palette and replace colors"},{{U"先确定少量主色、暗部色和高光色，加入调色板；同一材质尽量复用已有颜色。",U"Start with a small set of base, shadow and highlight colors and add them to the palette. Reuse colors for the same material."},{U"用吸管从画面拾色，再加入调色板。已有作品也可以使用提取颜色功能整理配色。",U"Pick colors from the canvas and add them to the palette. Extract colors from existing artwork to organize its palette."},{U"想统一更换某个颜色时使用颜色替换，先检查目标层、选区和处理范围，再确认结果。",U"Use Color Replacement to change a color consistently. Check the target layers, selection and scope before confirming."},{U"整理好的调色板可以保存以便其他作品复用。调整色板顺序前，先确认是否在使用索引色或颜色同步功能。",U"Save palettes for reuse. Before rearranging swatches, check whether indexed color or palette color synchronization is in use."}},{U"RGBA、索引色和灰度的颜色表达不同，转换色彩模式前先保留原工程。",U"RGBA, indexed color and grayscale represent colors differently. Keep the original project before converting modes."},{"tool.eyedropper","addForegroundToPalette","replaceColor","extractPaletteColors","savePalette"}},
{"linked-frames","create",{U"动画多帧一起变了：理解链接帧",U"Why several animation frames change together"},{{U"动画的每一列代表帧，图层与帧相交的位置是单元格。先确认选中的单元格属于哪个图层和帧。",U"Each timeline column is a frame; a layer/frame intersection is a cel. Check which layer and frame your selected cel belongs to."},{U"链接单元格共享图像，适合多个帧保持不变的背景。修改共享内容时，其他链接位置也会变化。",U"Linked cels share an image, which is useful for unchanged backgrounds. Editing shared content changes other linked positions too."},{U"需要单独修改某一帧时，先选中对应单元格并断开链接，再绘制变化。",U"To edit a frame independently, select its cel and disconnect the link before drawing."},{U"需要完全空白的下一帧时添加空白帧；需要复用内容时，根据是否应同步修改选择普通帧或链接帧。",U"Add a blank frame for an empty next pose. When reusing content, choose ordinary or linked frames according to whether edits should stay synchronized."},{U"发现整段动画意外变化时先撤销，再检查链接关系，避免逐帧重复修补共享图像。",U"Undo unexpected changes across an animation and inspect links before trying to repair shared content frame by frame."}},{U"“选中多个帧”和“帧之间有链接”是两件事，排查时都要检查。",U"Selecting multiple frames and linking cels are different. Check both when troubleshooting."},{"addBlankAnimationFrame","addLinkedAnimationFrame","disconnectAnimationCels","openAnimationCelProperties"}},
{"animation-timing","create",{U"动画太快、太慢或循环不顺",U"Fix animation timing and rough loops"},{{U"先把预览播放速度设为 100%，再判断动画本身的节奏，避免把临时预览倍率当成帧时长。",U"Set preview speed to 100% before judging timing so a temporary speed multiplier does not mislead you."},{U"在帧属性中调整时长：时长越大，该帧停留越久。停顿姿态可以更长，快速过渡可以更短。",U"Adjust duration in Frame Properties. Longer durations hold a pose longer; shorter ones create quicker transitions."},{U"使用洋葱皮比较相邻帧的位置，减少角色无意的抖动，尤其留意脚底或其他固定接触点。",U"Compare neighboring frames with onion skin to reduce unintended jitter, especially at feet or other fixed contact points."},{U"循环动画要比较末帧到首帧的衔接。首尾两帧完全相同可能产生额外停顿，按实际效果决定是否保留。",U"Check the last-to-first transition. Identical first and last poses can add a pause; keep them only if that timing is intended."},{U"导出后再播放一遍，确认帧范围和速度；不要只根据编辑器中一次预览判断最终文件。",U"Play the exported result to verify its frame range and timing rather than relying only on an editor preview."}},{U"调整预览播放倍率方便检查动作，但应通过帧时长设计作品的实际节奏。",U"Preview speed helps inspect motion; frame durations define the intended timing."},{"openAnimationFrameProperties","animationPlaybackSpeed100","toggleOnionSkin","toggleAnimationPlayback"}},
{"sprite-sheet","create",{U"把动画导出为游戏用精灵表",U"Export animation as a game sprite sheet"},{{U"先确认动画各帧的画布尺寸一致，以及角色在帧中的基准位置稳定，避免引擎播放时跳动。",U"Check consistent canvas dimensions and a stable character origin across frames to avoid jitter in the engine."},{U"从「文件 → 导出」选择精灵表，检查输出帧范围、排列方式以及每行或每列的设置。",U"Choose sprite sheet export from File → Export and check the frame range, layout and row or column settings."},{U"根据引擎导入要求设置边距和间距；在引擎中切片时使用相同参数，否则会出现偏移或切到相邻帧。",U"Set margins and spacing to match the engine’s import requirements. Use the same values when slicing in the engine."},{U"像素素材通常按原始尺寸输出，让引擎控制显示倍率。需要透明背景时选择支持透明通道的格式。",U"Usually export pixel assets at their original size and let the engine control display scale. Choose an alpha-capable format for transparency."},{U"导入引擎后检查纹理过滤和缩放方式。图片本身清晰而游戏里模糊时，也要检查引擎设置。",U"Check texture filtering and scaling after importing. If a sharp image looks blurry in-game, inspect engine settings too."}},{U"精灵表保存帧图像；播放顺序、帧时长等信息还需要按引擎的导入流程配置。",U"A sprite sheet stores frame images; configure playback order and timing through your engine’s import workflow."},{"exportSpriteSheet","exportAllFrames"}},
{"reference","create",{U"使用参考图而不改动画面",U"Use reference images alongside your artwork"},{{U"使用「添加参考图」或「粘贴为参考图」放入素材；参考图用于辅助观察，不等同于普通绘画图层。",U"Use Add Reference Image or Paste as Reference Image. A reference assists observation and is not an ordinary painting layer."},{U"调整参考图位置、缩放和透明度，让它不遮住正在绘制的区域。",U"Adjust reference position, scale and opacity so it does not obstruct your working area."},{U"摆好后锁定参考图，减少误拖动；需要调整时再解锁。",U"Lock a reference after positioning it to avoid accidental drags; unlock it when adjustments are needed."},{U"希望参考图固定在屏幕上时使用独立浮动，或者打开参考图浮窗；需要和画布一起移动时关闭独立浮动。",U"Use independent floating or a reference window to keep it separate from canvas movement. Disable independent floating when it should follow the canvas."}},{U"如果目的是让图片成为作品中的像素内容，应导入到绘画内容中，而不是只添加为参考图。",U"If an image should become artwork pixels, import it into the artwork rather than adding only a reference."},{}},
{"seamless","create",{U"检查无缝纹理和对称图案",U"Check seamless textures and symmetry"},{{U"绘制地面、水面等重复纹理时，在「窗口 → 平铺预览」选择横向、纵向或包围平铺。",U"For repeating ground or water textures, choose horizontal, vertical or surrounding tiling in Window → Tile Repeat."},{U"观察相邻副本交界处是否有断线、明暗突变或重复感明显的孤立图案，再回到边缘修改。",U"Inspect joins between copies for broken lines, abrupt tone changes or conspicuous motifs, then adjust the edges."},{U"使用对称功能绘制对称角色或装饰前，先确认对称轴和中心位置，在空白层试画。",U"Before drawing symmetrical characters or ornaments, check the symmetry axes and center, then test on an empty layer."},{U"完成对称部分后关闭不再需要的对称模式，避免后续补细节时在另一侧产生额外笔触。",U"Turn off symmetry modes when finished so detail work does not create unwanted strokes elsewhere."}},{U"平铺预览用于检查接缝，不会自动把导出图片扩展成多份纹理。",U"Tile preview helps inspect seams; it does not automatically export multiple copies of the texture."},{"tileRepeatBoth","tileRepeatOff","toggleSymmetryHorizontal","toggleSymmetryVertical","resetSymmetryCenter"}},
{"performance","fix",{U"复杂画布操作卡顿怎么排查",U"Troubleshoot slow operations on complex canvases"},{{U"先保存工程，观察卡顿出现在绘制、移动选区、播放动画还是滤镜预览，尽量找到可以重复触发的一步。",U"Save first and identify whether the slowdown occurs while drawing, moving a selection, playing animation or previewing a filter. Find a repeatable step."},{U"滤镜调参时关闭实时预览再比较；动画卡顿时先停播，检查是否只有播放状态下才慢。",U"Try disabling live preview while adjusting filters. Stop animation playback to see whether the slowdown is limited to playback."},{U"移动选区前检查是否同时选中了很多帧或图层。只需移动一处时，把编辑范围缩小到目标层和帧。",U"Check whether many layers or frames are selected before moving content. Restrict editing to the intended layer and frame when possible."},{U"临时关闭不需要的洋葱皮、平铺预览或额外预览面板，比较操作是否改善，再逐项恢复。",U"Temporarily turn off unneeded onion skin, tile repeat or extra preview panels, compare responsiveness, then restore them one at a time."},{U"反馈时记录画布尺寸、图层数、帧数、操作范围和持续时间，并附上对应诊断记录；有条件时提供能复现的工程副本。",U"Report canvas dimensions, layer and frame counts, edit scope and delay duration, with diagnostic records and a reproducible project copy if possible."}},{U"不要为了测试速度直接删除原作品的图层或动画帧；需要简化工程时使用副本。",U"Do not delete original layers or frames just to test performance. Simplify a copy instead."},{"save","toggleOnionSkin","tileRepeatOff","toggleAnimationPlayback"}},
{"shortcut-trouble","fix",{U"快捷键无效或执行了别的操作",U"Shortcuts do nothing or trigger another action"},{{U"先检查输入焦点：正在编辑名称、数值或文字时，按键可能由输入框处理。结束输入后再回到目标面板。",U"Check focus first. A name, number or text field may handle keys while editing. Finish input and return to the intended panel."},{U"关闭不再使用的弹窗或菜单。某些操作在弹窗打开、拖动或绘制尚未结束时会被阻止。",U"Close unused dialogs or menus. Some commands are blocked during dialogs, drags or unfinished strokes."},{U"打开下方快捷键设置，按命令名称查找实际绑定，检查是否被修改、清空或与其他命令冲突。",U"Open Shortcut settings below, find the command and inspect its binding for changes, missing keys or conflicts."},{U"同一按键在画布和时间轴中可能有不同用途。例如取消选区与复制动画单元格需要结合当前操作区域判断。",U"A key may have different uses on the canvas and timeline. Deselecting and copying animation cels depend on the current operation context."},{U"尝试通过菜单执行同一命令：菜单有效而快捷键无效时，优先检查焦点与绑定；菜单也无效时，检查文档和选择状态。",U"Try the equivalent menu command. If it works, check focus and bindings. If it also fails, check document and selection state."}},{U"本帮助中的按键来自当前设置；“未设置”的命令可在快捷键设置中自行绑定。",U"Keys in this guide come from your settings. Assign commands marked Not assigned in Shortcut settings."},{"openShortcutSettings","deselect","copyAnimationCel"}},
{"export-trouble","fix",{U"导出模糊、背景不透明或帧不完整",U"Fix blurry exports, opaque backgrounds or missing frames"},{{U"先确认导出的是当前静态帧、动画还是帧序列；只导出静态图片不会包含整段动画。",U"Check whether you are exporting a still frame, animation or frame sequence. A still image does not contain the whole animation."},{U"检查图层可见性与帧范围，确认需要输出的内容已包含在导出范围中。",U"Check layer visibility and frame range to ensure all intended content is included."},{U"透明背景需要支持透明度的格式，并且画面中不能有覆盖全画布的不透明背景层。",U"Transparency requires a format with transparency support and no opaque background layer covering the canvas."},{U"像素边缘模糊时对比原尺寸导出，检查是否使用了非整数倍率或平滑插值。也要确认查看器没有额外平滑缩放。",U"Compare a native-size export if edges look blurry. Check for fractional scaling or smooth interpolation, including scaling applied by the viewer."},{U"导出报错时记录错误信息，尝试另一个有写入权限的目录，并检查目标文件是否被其他程序占用。保留可编辑工程后再排查。",U"If export fails, record the error, try another writable folder and check whether another program holds the destination file. Keep an editable project saved while troubleshooting."}},{U"先用少量帧和原尺寸验证设置，再导出整段动画，可以更快发现范围和格式问题。",U"Verify settings with a few frames at native size before exporting the full animation."},{"exportDocument","exportAllFrames","save"}},
};return values;}
inline const std::vector<Article>& tipsArticles(){static const std::vector<Article> values{
{"modifier-brushSizeAdjust","start",{U"不离开画布调整笔刷尺寸",U"Resize brushes without leaving the canvas"},{{U"按住对应修饰键，在画布内左右移动鼠标调整笔刷尺寸，无需按下左键；松开后继续绘制。",U"Hold the modifier and move horizontally over the canvas to resize the brush without pressing the left mouse button. Release to resume drawing."},{U"将指针放在画布上，按住修饰键并滚动滚轮调整笔刷尺寸。不要与普通滚轮的视图操作混淆。",U"Hold the modifier and scroll over the canvas to change brush size. This differs from ordinary wheel navigation."}},{U"",U""},{"brushSizeAdjust","brushSizeWheelAdjust"}},
{"modifier-lines","start",{U"连续直线与方向约束",U"Connected lines and direction constraints"},{{U"使用支持直线连接的绘画工具时，按住修饰键连接上一落点与新的落点，适合连续折线或像素轮廓。",U"With a drawing tool that supports line connection, hold the modifier to connect the previous point to the new point. Useful for connected segments and outlines."},{U"绘制直线时按住方向约束修饰键，让线段沿允许的方向变化，便于画水平、垂直或规则斜线。",U"Hold the direction constraint while drawing a line to restrict it to supported directions for horizontal, vertical or regular diagonal segments."}},{U"",U""},{"lineConnectionMode","constrainLineDirections"}},
{"modifier-copy","start",{U"拖动复制与轴向移动",U"Drag copies and constrain movement"},{{U"已有选区时，在开始移动内容前按住复制修饰键再拖动，保留原位置内容并移动副本。先确认当前工具和图层。",U"With a selection, hold the copy modifier before dragging its content to move a copy while keeping the original. Check the active tool and layer first."},{U"移动图层内容时，开始拖动前按住复制图层修饰键，以副本进行移动。与只复制选区的操作区分使用。",U"Hold the layer-copy modifier before dragging layer content to move a duplicate. Distinguish this from copying only selected pixels."},{U"移动内容时按住轴向约束修饰键，限制移动方向，适合只改变横向或纵向位置。",U"Hold the axis constraint while moving content to restrict movement, useful for horizontal or vertical positioning."}},{U"",U""},{"copySelectionContent","copyLayerOnDrag","constrainAxis"}},
{"modifier-selection","start",{U"加选与精确变换",U"Add selections and transform precisely"},{{U"使用选区工具时按住加选修饰键，再绘制另一块选区，将范围加入已有选区；需要减选或交集时使用对应选区模式。",U"Hold the add modifier while creating another selection area to add it to the existing selection. Use the relevant modes for subtraction or intersection."},{U"拖动选区变换缩放手柄时按住比例约束修饰键，保持宽高比例，避免角色被拉伸。",U"Hold the proportional modifier while dragging a selection scale handle to preserve aspect ratio."},{U"缩放选区内容时按住整数缩放修饰键，让缩放使用整数倍率，适合保留像素块的规则尺寸。",U"Hold the integer-scale modifier while scaling selected content to use integer magnification and preserve regular pixel blocks."},{U"旋转选区内容时按住吸附修饰键，让角度按固定步进变化；此操作修改内容，不是旋转视图。",U"Hold the snap modifier while rotating selected content to use angle increments. This changes content rather than the view."}},{U"",U""},{"addToSelection","proportionalSelectionTransform","integerSelectionScale","snapSelectionRotation"}},
{"modifier-view","start",{U"旋转视图吸附与复位",U"Snap and reset view rotation"},{{U"旋转画布视图时按住吸附修饰键，让观看角度按固定步进变化，不改变作品像素。",U"Hold the snap modifier while rotating the canvas view to use angle increments without changing artwork pixels."},{U"使用旋转视图工具时按住重置修饰键，将视图旋转恢复，便于回到正常方向继续绘制。",U"Use the reset modifier with the view rotation tool to restore the viewing angle and continue drawing upright."}},{U"",U""},{"snapViewRotation","resetViewRotation"}},
{"temporary-tools","start",{U"按住临时切换工具，松开继续画",U"Hold to switch tools temporarily"},{{U"绘制途中，按住临时吸管键取色，松开后接着画；不用来回点击工具栏。",U"While drawing, hold the temporary eyedropper key to sample a color, then release to continue without visiting the toolbar."},{U"按住临时抓手键并拖动，可以平移画布；临时移动键则用于移动内容，适合快速修正位置。",U"Hold the temporary Hand key and drag to pan. Temporary Move edits content, useful for quick position corrections."}},{U"其他工具也可以在快捷键设置中配置临时切换键。",U"Configure temporary bindings for other tools in Shortcut settings."},{"tool.eyedropper.quick","tool.hand.quick","tool.move.quick"}},
{"feature-tween","fix",{U"动画补间与可复用运动路径",U"Animation tweening and reusable motion paths"},{{U"在时间轴准备起止姿态，再打开动画补间设置。先确认参与的图层或组和帧范围，避免让不需要移动的背景参与。",U"Prepare start and end poses in the timeline, then open tween settings. Check layers or groups and frame range so static backgrounds are not included accidentally."},{U"根据效果选择运动、形变或淡入淡出，设置中间帧数量并预览；像素画需要特别检查轮廓在中间帧是否合理。",U"Choose motion, deformation or fading as appropriate, set intermediate frames and preview. Inspect pixel outlines in the generated poses."},{U"通过缓动曲线控制变化快慢。曲线调整进度分布，不改变每帧时长；实际播放节奏仍需结合帧时长检查。",U"Use easing curves to control progress over time. Easing does not change frame duration, so check both for timing."},{U"需要沿弧线或复杂路线移动时打开路径编辑器。路径可保存到路径库，在其他工程中载入复用；载入后检查锚点和画布范围。",U"Open the path editor for curved or complex movement. Save paths to the library for reuse in other projects, then check anchors and canvas bounds after loading."}},{U"先预览再生成；锁定层、背景层和部分特殊图层可能不参与补间，以窗口提示的范围为准。",U"Preview before generating. Locked, background and some specialized layers may be excluded; check the scope shown in the dialog."},{}},
{"feature-tiles","fix",{U"瓦片地图与自由瓦片",U"Tilemaps and free tiles"},{{U"规则地形适合瓦片地图图层：先准备瓦片集，再用瓦片搭建重复地图，减少逐块复制像素的工作。",U"Use tilemap layers for regular terrain. Prepare a tileset and build repeated maps with tiles instead of copying pixels manually."},{U"注意编辑、创建、混合和绘制等模式的区别，操作前查看当前模式。修改共享瓦片源可能影响所有使用它的位置。",U"Check whether Edit, Create, Hybrid or Paint mode is active. Changes to a shared tile source can affect all its uses."},{U"需要更自由地摆放重复素材时使用自由瓦片，区分瓦片源属性与实例属性：前者管理素材，后者管理摆放的对象。",U"Use free tiles for more flexible placement. Source properties manage the asset; instance properties manage placed objects."},{U"可对自由瓦片实例旋转或镜像，快速制作变化。需要直接按像素绘制时，先确认是否应转换为栅格图层，并保留副本。",U"Rotate or mirror free-tile instances for variations. If direct pixel editing is needed, consider raster conversion and retain a copy."}},{U"改一个地方却多处一起变化时，先检查是否引用了同一瓦片源。",U"If several locations change together, check whether they share a tile source."},{"newTilemapLayer","newFreeTileLayer","tilemapModeEdit","tilemapModePaint","openFreeTileSourceProperties","openFreeTileInstanceProperties"}},
{"feature-masks","fix",{U"蒙版、剪贴与图层样式",U"Masks, clipping and layer styles"},{{U"想暂时隐藏部分内容而保留原图时，使用图层或组蒙版；绘制前确认当前编辑的是图像还是蒙版。",U"Use a layer or group mask to hide parts while retaining the original image. Check whether you are editing the image or mask."},{U"需要让上色受到下方内容范围约束时，可尝试剪贴蒙版。先检查图层顺序和下方内容是否存在。",U"Try a clipping mask to constrain color to content below. Check layer order and the presence of underlying content."},{U"通过图层样式统一设置效果；对相似图层使用复制、粘贴样式，减少重复调参。",U"Configure effects through layer styles. Copy and paste styles between similar layers to avoid repeated setup."},{U"效果不对时先切换样式开关比较，不必立即清除样式或合并图层。",U"Toggle styles to compare results before clearing them or merging layers."}},{U"蒙版、剪贴和图层可见性都可能让内容暂时不可见，排查时分别检查。",U"Masks, clipping and layer visibility can all hide content. Check them separately."},{"toggleLayerMask","toggleGroupMask","toggleClippingMask","openLayerStyles","copyLayerStyles","pasteLayerStyles"}},
{"feature-fast-edit","create",{U"复制合并、快速描边与内容对齐",U"Merged copy, quick outlines and content alignment"},{{U"需要把多层可见效果作为一张图复制时，使用复制合并，避免为了复制而破坏原来的图层结构。",U"Use Copy Merged to copy the visible composite without merging the original layer structure."},{U"粘贴为新图层方便继续合成，粘贴为新工程适合独立处理素材；根据目标选择不同粘贴命令。",U"Paste as New Layer for compositing, or as New Document for independent editing. Choose the command for your destination."},{U"给图标或角色加轮廓时使用描边或快速描边，先确认选区、颜色和厚度，检查是否影响透明边缘。",U"Use Outline or Quick Outline for icons and characters. Check selection, color and thickness, especially at transparent edges."},{U"用内容居中、翻转和固定角度旋转快速整理素材。内容变换会修改像素布局，与镜像视图不同。",U"Use content centering, flipping and fixed-angle rotation to arrange assets. Content transformations change pixel layout, unlike view mirroring."}},{U"多层效果复制前检查可见性，粘贴后检查目标图层和位置。",U"Check visibility before copying a composite and the target layer and position after pasting."},{"copyMerged","pasteAsNewLayer","pasteAsNewDocument","quickOutline","outline","centerContentBoth","flipHorizontal","rotateContentClockwise"}},
{"feature-timelapse","fix",{U"缩时录像记录创作过程",U"Record your process with timelapse"},{{U"从「文件 → 缩时视频」查看录制状态与设置，开始正式绘画前先确认已启用需要的记录功能。",U"Open File → Timelapse to inspect recording status and settings before starting your artwork."},{U"按需要决定是否记录撤销步骤：记录全部尝试适合展示探索过程，只保留有效步骤更适合简洁回放。",U"Choose whether to record undo steps. Including attempts shows exploration; keeping effective steps makes a cleaner replay."},{U"作品完成后预览录像，再设置导出参数并导出。保存工程和导出录像是不同操作。",U"Preview the recording when finished, then configure and export it. Saving a project and exporting a recording are separate actions."},{U"录像保存在本机录像库；另存工程时留意是否携带录像，迁移电脑前单独检查录像是否一起转移。",U"Recordings are kept in the local recording library. Check whether Save As includes recordings, and verify transfer when moving to another computer."}},{U"未记录的过去操作无法靠后期开启录像补回。",U"Enabling recording later cannot reconstruct earlier unrecorded actions."},{"openTimelapse","saveAs"}},
{"feature-layout","create",{U"浮窗、工作区布局与快捷面板",U"Floating panels, layouts and popup panels"},{{U"绘画与动画可以使用不同布局：按需要安排调色板、图层、预览和时间轴，再保存工作区布局。",U"Use different layouts for drawing and animation. Arrange Palette, Layers, Preview and timeline, then save the workspace layout."},{U"通过工作区管理切换布局；面板不见时先检查窗口菜单中的显示选项，再考虑重置布局。",U"Switch layouts in workspace management. Check panel visibility in Window before resetting a layout."},{U"快捷面板适合临时取色或选择笔刷，下方可查看颜色、调色板、图层、预览、瓦片集和笔刷库的当前呼出键。",U"Popup panels are useful for brief color or brush selection. Current bindings for Color, Palette, Layers, Preview, Tileset and Brush Library appear below."},{U"窄面板中的部分操作会收进更多菜单；找不到按钮时先展开更多操作，或适当加宽面板。",U"Narrow panels move some actions into their overflow menus. Check More actions or widen the panel if a button is missing."}},{U"调整布局只改变工作环境，不应当作修改作品的撤销步骤。",U"Layout changes affect the workspace rather than artwork history."},{"saveWorkspaceLayout","openWorkspaceManager","resetWorkspaceLayout","popupColorPanel","popupPalettePanel","popupLayersPanel","popupPreviewPanel","popupTilesetPanel","popupBrushLibraryPanel"}},
{"feature-tablet","fix",{U"数位笔、触控手势与辅助条",U"Pen input, touch gestures and the helper bar"},{{U"使用触控设备时在偏好设置中检查触控布局、辅助条和手势选项，按设备与习惯启用。",U"On touch devices, inspect touch layout, helper bar and gesture options in Preferences and enable those suited to your device."},{U"启用对应手势后，可以用双指撤销、三指重做、长按取色；先在空白工程测试，避免系统手势或驱动设置冲突。",U"When enabled, use two-finger undo, three-finger redo and long-press sampling. Test in a blank project for system or driver conflicts."},{U"没有物理键盘时可用辅助条修饰键和选区微调。留意按住状态或锁定状态，完成操作后解除不需要的修饰键。",U"Use helper-bar modifiers and selection nudges without a physical keyboard. Watch held or latched states and release them after use."},{U"笔压异常时使用笔输入测试，观察压力变化，再调整笔刷动态；同时用鼠标对比以区分工具设置与设备输入问题。",U"Use the pen input test to inspect pressure, then adjust brush dynamics. Compare with a mouse to distinguish tool settings from input issues."}},{U"触控手势是否可用取决于启用状态和设备输入支持。",U"Gesture availability depends on settings and device input support."},{"openPreferences","undo","redo"}},
{"feature-import","fix",{U"精灵表导入、切片与工程交换",U"Sprite sheet import, slices and project exchange"},{{U"现成精灵表可通过导入精灵表拆成动画帧；设置帧宽高、间距和边缘处理，检查预览是否切到相邻素材。",U"Import a sprite sheet as animation frames. Set frame dimensions, spacing and edge handling, then inspect the slicing preview."},{U"图片序列适合将外部动画逐帧导入；导入后核对顺序和时长，尤其留意文件名编号顺序。",U"Image sequences bring external animation frames into the project. Verify order and durations, especially filename numbering."},{U"切片用于标记素材区域，可通过切片工具、自动切片和切片属性管理；交付前核对命名和区域。",U"Slices mark asset regions. Manage them through the Slice tool, Auto Slice and Slice Properties; check names and bounds before delivery."},{U"与其他软件交换 .ase 或 .aseprite 工程时，阅读保存时的兼容性提示。保留原生工程，避免特色数据在格式转换中丢失。",U"Read compatibility notices when exchanging .ase or .aseprite files. Keep a native project to preserve specialized data during conversion."}},{U"导入成功后先检查帧数、尺寸和图层，再覆盖现有工程。",U"Verify frame count, dimensions and layers before overwriting an existing project."},{"tool.slice","openAutoSlice","openSliceProperties","saveAs"}},
};return values;}
}
